{"yaml":"classes:
  Order:
    properties:
      paymentTerm: {type: text}
      totalLineAmount: {type: number}
      totalAllowanceAmount: {type: number}
      totalChargeAmount: {type: number}
      totalBeforeTax: {type: number}
      totalIncludingTax: {type: number}
      prepaidAmount: {type: number}
      roundingAmount: {type: number}
      amountDueForPayment: {type: number}"}

